from __future__ import absolute_import
import re
import time
from taf.ul.trs_e2e_fw.lib.oam.coam_cbts_cu.base import BaseClass
from taf.ul.trs_e2e_fw.lib.utils.decorators import check_rat
from taf.ul.trs_e2e_fw.lib.oam.coam_cbts_cu.exceptions import UnsuccessfulStatus
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger

logger = BackgroundLogger.Instance()


class Certificate(BaseClass):
    """Certificate"""
    def __init__(self):
        super(Certificate, self).__init__()

    @check_rat
    def certificate_configure(self, **kwargs):
        """Configure certificate"""
        operation = kwargs.pop("operation", "''")
        timeout = kwargs.pop("timeout", 60)
        alias = kwargs.pop("alias", "default")
        kwargs = {key: value for key, value in list(kwargs.items()) if key not in ["operation", "timeout", "alias"]}

        logger.debug("Performing operation  {}...".format(operation.upper().replace("_", " ")))
        if operation.lower() == 'set_certificate_automatic_management':
            return self._set_certificate_automatic_management(timeout, alias, **kwargs)
        elif operation.lower() == 'cmp_update_key':
            return self._cmp_update_key(timeout, alias, **kwargs)
        elif operation.lower() == 'install_cmp_certificate':
            return self._install_cmp_certificate(timeout, alias, **kwargs)
        elif operation.lower() == 'install_certificate':
            return self._install_certificate(timeout, alias, **kwargs)
        elif operation.lower() == 'get_certificate_list':
            return self._get_certificate_list(alias)
        elif operation.lower() == 'get_certificate_details':
            return self._get_certificate_details(timeout, alias, **kwargs)
        elif operation.lower() == 'restore_vendor_certificate':
            return self._restore_vendor_certificate(timeout, alias)
        elif operation.lower() == 'delete_cert':
            return self._delete_certificate(timeout, alias, **kwargs)
        elif operation.lower() == 'update_certificate_revocation_list':
            return self._update_certificate_revocation_list(timeout, alias)
        elif operation.lower() == 'get_certificate_revocation_list':
            return self._get_certificate_revocation_list(alias)
        else:
            raise Exception("Operation {} not supported".format(operation))

    def _set_certificate_automatic_management(self, timeout, alias, **kwargs):
        reference_number = kwargs['reference_number']
        preshared_key = kwargs['preshared_key']
        key_pool_type = kwargs.get('key_pool_type', 'RSA')
        self.factory.cu_oam.update_cmp_server_settings(ref_number=reference_number, psk_key=preshared_key, key_pool_type=key_pool_type,
                                                       timeout=timeout, connection=alias)

    def _cmp_update_key(self, timeout, alias, **kwargs):
        key_pool_type = kwargs.get('key_pool_type', 'RSA')
        self.factory.cu_oam.trigger_cmp_server_key_update(timeout=timeout, connection=alias, key_pool_type=key_pool_type)

    def _install_cmp_certificate(self, timeout, alias, **kwargs):
        key_pool_type = kwargs.get('key_pool_type', 'RSA')
        self.factory.cu_oam.trigger_certificate_initialization(timeout=timeout, connection=alias,
                                                               key_pool_type=key_pool_type)

    def _get_certificate_list(self, alias):
        return self.factory.cu_oam.get_operator_certificate_list(connection=alias)

    def _get_certificate_details(self, timeout, alias, **kwargs):
        logger.debug("Get cert details")
        certificate_id = kwargs.get('certificate_id')
        response = self.factory.cu_oam.get_operator_certificate(certificate_id=certificate_id,timeout=timeout, connection=alias)
        return response

    def _install_certificate(self, timeout, alias, **kwargs):
        cert_file = kwargs.get('cert_file')
        cert_type = kwargs.get('cert_type')
        return self.factory.cu_oam.install_operators_certificate(
            certificate_file_path=cert_file, certificate_type=cert_type.upper(), timeout=timeout, connection=alias)

    def _restore_vendor_certificate(self, timeout, alias):
        self.factory.cu_oam.delete_all_operator_certificates(timeout, alias)

    def _match_and_get_certificate_id(self, subject, certificate_list):
        """
        Matches subject argument from user and subject fetched from CU WebEm.
        returns: certificate_id
        """
        try:
            for certificate in certificate_list:
                extracted_subject = re.findall(r"\/(.*)",certificate['details']['issued_to'])[0]
                logger.debug('Subject from user is : {}'.format(subject))
                logger.debug('Subject fetched from CU is : {}'.format(extracted_subject))
                if subject == extracted_subject:
                    logger.info("Subject {} matched".format(subject))
                    certificate_id = certificate['id']
                    return certificate_id
            else:
                raise Exception("None of the available certificates matched with the given subject")
        except Exception as e:
            raise Exception("Failed to fetch Certificate Id due to : {}".format(e))

    def _verify_delete_certificate_status(self, certificate_id, timeout, alias):
        """
        Deletes certificates and verify if status is successful.
        returns: result_dict
        raises: UnsuccessfulStatus Exception if delete operation unsuccessful
        """
        result_dict = self.factory.cu_oam.delete_operator_certificate(certificate_id=certificate_id, timeout=timeout, connection=alias)
        output = self._verify_status(result_dict, "Successful")
        if not output and result_dict["status"].lower() == "failed":
            raise UnsuccessfulStatus("Delete certificate unsuccessful.\nResponse status is : {}.\nResult dict is:{}".format(
                result_dict["status"], result_dict))
        elif not output and result_dict["status"].lower() == 'ongoing':
            time.sleep(10)
            certificate_list = self.factory.cu_oam.get_operator_certificate_list(connection=alias)
            certificate_ids = [certificate['id'] for certificate in certificate_list]
            if certificate_id in certificate_ids:
                raise UnsuccessfulStatus("Delete certificate unsuccessful.\nResponse status is : {}.\nResult dict is:{}".format(
                    result_dict["status"], result_dict))
            else:
                logger.info("Certificate with id {} deleted succesfully".format(certificate_id))
        else:
            logger.info("Certificate with id {} deleted succesfully".format(certificate_id))

    def _delete_certificate(self, timeout, alias, **kwargs):
        """
        Delete certificate

        :param subject: issued_to value.
        :param all_certs: If True deletes all the certificates, else deletes certificate with subject specified by user.
                          By default True.

        """
        all_certs = kwargs.get('all_certs', False)
        certificate_list = self.factory.cu_oam.get_operator_certificate_list(connection=alias)
        if not all_certs:
            subject = kwargs["subject"]
            certificate_id = self._match_and_get_certificate_id(subject, certificate_list)

            self._verify_delete_certificate_status(certificate_id, timeout, alias)

        else:
            self._restore_vendor_certificate(timeout, alias)
            for certificate in certificate_list:
                logger.info("certificate is :{}".format(certificate))
                certificate_id = certificate['id']
                if certificate['details']['trust_chain'] and certificate['details']['trust_chain'].name == 'BTS Operator Certificate Trust Chain':
                    logger.info('Ignored vendor certificate with certificate id {}'.format(certificate_id))
                else:
                    logger.info("Deleting the certificate with id {} ...".format(certificate_id))
                    self._verify_delete_certificate_status(certificate_id, timeout, alias)

    def _update_certificate_revocation_list(self, timeout, alias):
        """
        Trigger CRL information update
        """
        return self.factory.cu_oam.trigger_crl_information_update(timeout=timeout, connection=alias)

    def _get_certificate_revocation_list(self, alias):
        """
        Get CRL information
        """
        return self.factory.cu_oam.get_current_crl(connection=alias)
